contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address a) public payable {
        require(a != address(0));
        require(c.balances(a) == 0);

        uint256 beforeBalance = c.balances(a); if (__ESBMC_reverted()) return;
        uint256 beforeReserve = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(!reverted && c.balances(a) == beforeBalance && address(c).balance == beforeReserve);
    }

    receive() external payable {}
}

